properties.query:
let reg_events = SecurityEvent | where EventID == 4657 and ObjectName has_any ("SAM", "SYSTEM", "SECURITY") | summarize reg_time=min(TimeGenerated) by SubjectUserName, Computer;
let cred_events = SecurityEvent | where EventID == 4663 and ObjectName has "lsass" | summarize cred_time=min(TimeGenerated) by SubjectUserName, Computer;
let golden_events = SecurityEvent | where EventID == 4768 and TicketEncryptionType == "0x17" | summarize golden_time=min(TimeGenerated) by TargetUserName;
reg_events | join kind=inner cred_events on SubjectUserName, Computer | where cred_time - reg_time between (0min .. 120min)
